-- A bigger shop: 12 more coin ships and 6 more diamond ships (server only, no app update needed).
on conflict (id) do nothing;
-- order the shop: coin ships by price, then diamond ships by price
with o as (select id, row_number() over (order by (gems > 0), price, gems) * 10 as s from public.shop_ships where not secret)
update public.shop_ships x set sort = o.s from o where x.id = o.id;
